package com.steven.assets.service.srpp.report;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class SrppNamedCashBuyBudgetTest {
    static final JsonNodeFactory F=JsonNodeFactory.instance;
    static final LocalDate DAY=LocalDate.of(2026,11,19);
    static final String PLAN=SrppNamedCashBuyBudget.PLAN_ID;
    static ObjectNode cfg(){return F.objectNode().put("enabled",true).put("plan_id",PLAN).put("effective_date","2026-11-18").put("total_buy_budget_twd","400000").put("budget_includes_buy_fees",true).put("budget_includes_pending_orders",true).put("budget_includes_immutable_reservations",true).put("reset_budget_automatically",false);}
    static ObjectNode source(String key){ObjectNode s=F.objectNode().put("verified",true).put("coverage","COMPLETE").put("status","VERIFIED");s.putArray(key);return s;}
    static ObjectNode plan(){ObjectNode s=source("unused").put("planId",PLAN).put("source_ref","official-plan");s.set("fills",source("rows").put("startDate","2026-11-18").put("endDate",DAY.toString()));return s;}
    static ObjectNode fill(ObjectNode p,String id,String amount,String fees){return p.withObject("fills").withArray("rows").addObject().put("fillId",id).put("planId",PLAN).put("symbol","00881").put("market","台股").put("side","BUY").put("confirmed",true).put("tradeDate","2026-11-18").put("shares","1000").put("price",new java.math.BigDecimal(amount).divide(new java.math.BigDecimal("1000")).toPlainString()).put("amount",amount).put("fees",fees).put("source_ref","official-fill:"+id);}
    static ObjectNode order(ObjectNode p,String id){return p.withArray("orders").addObject().put("orderId",id).put("symbol","00881").put("market","台股").put("side","BUY").put("planId",PLAN).put("currency","TWD").put("remainingShares","1000").put("limitPrice","40").put("remainingFees","57");}
    static ObjectNode reserve(ObjectNode p,String id){return p.withArray("rows").addObject().put("reservationId",id).put("symbol","00881").put("market","台股").put("action","BUY").put("status","ACTIVE").put("currency","TWD").put("strategy",SrppNamedCashBuyBudget.STRATEGY).put("amount","40000").put("fees","57");}
    static JsonNode run(ObjectNode p,ObjectNode o,ObjectNode r){return SrppNamedCashBuyBudget.evaluate(cfg(),p,o,r,DAY);}
    @Test void verifiedEmptyIsKnownZeroWithoutInventedSpent(){ObjectNode p=plan();p.put("spentTwd","399999");JsonNode n=run(p,source("orders"),source("rows"));assertThat(n.path("status").asText()).isEqualTo("PASS");assertThat(n.path("remainingTwd").asText()).isEqualTo("400000");assertThat(n.path("accountingEntries")).isEmpty();assertThat(n.path("tradeAuthorization").asBoolean()).isFalse();}
    @Test void crossDayActualFillsIncludeFeesAndCanonicalEntries(){ObjectNode p=plan();fill(p,"yesterday","40000","57");fill(p,"today","50000","71").put("tradeDate",DAY.toString());JsonNode n=run(p,source("orders"),source("rows"));assertThat(n.path("usedTwd").asText()).isEqualTo("90128");assertThat(n.path("remainingTwd").asText()).isEqualTo("309872");assertThat(n.path("accountingEntries").get(0).path("id").asText()).isEqualTo("FILL:yesterday");}
    @Test void pendingAndUnlinkedReservationsIncludeFees(){ObjectNode o=source("orders"),r=source("rows");order(o,"o");reserve(r,"r");JsonNode n=run(plan(),o,r);assertThat(n.path("committedTwd").asText()).isEqualTo("80114");assertThat(n.path("accountingEntries").size()).isEqualTo(2);}
    @Test void linkedPartialOrderPreservesLargerImmutableCommitmentAndInheritsOfficialPlan(){ObjectNode o=source("orders"),r=source("rows");ObjectNode row=order(o,"o");row.remove("planId");row.put("remainingShares","500");reserve(r,"r").put("linkedOrderId","o").put("amount","120000");ObjectNode p=plan();fill(p,"partial","20000","29");JsonNode n=run(p,o,r);assertThat(n.path("status").asText()).isEqualTo("PASS");assertThat(n.path("usedTwd").asText()).isEqualTo("20029");assertThat(n.path("committedTwd").asText()).isEqualTo("120057");assertThat(n.path("accountingEntries").size()).isEqualTo(2);assertThat(n.path("accountingEntries").get(1).path("id").asText()).isEqualTo("PENDING:o");}
    @Test void independentPathsAreNotThisPlanButUnknownIsNotZero(){ObjectNode o=source("orders"),r=source("rows");ObjectNode a=order(o,"a");a.remove("planId");a.put("strategy","NAMED_DEEP_DRAWDOWN_D215");reserve(r,"b").put("strategy","SHORT_TERM_D173");assertThat(run(plan(),o,r).path("remainingTwd").asText()).isEqualTo("400000");a.remove("strategy");JsonNode n=run(plan(),o,r);assertThat(n.path("status").asText()).isEqualTo("UNAVAILABLE");assertThat(n.path("remainingTwd").isNull()).isTrue();assertThat(n.path("accountingEntries")).isEmpty();}
    @Test void fullBudgetIsPassZeroAndExcessIsBlocked(){ObjectNode p=plan();fill(p,"f","399900","100");assertThat(run(p,source("orders"),source("rows")).path("status").asText()).isEqualTo("PASS");assertThat(run(p,source("orders"),source("rows")).path("remainingTwd").asText()).isEqualTo("0");((ObjectNode)p.withObject("fills").withArray("rows").get(0)).put("fees","101");JsonNode n=run(p,source("orders"),source("rows"));assertThat(n.path("status").asText()).isEqualTo("BLOCKED");assertThat(n.path("remainingTwd").asText()).isEqualTo("0");}
    @Test void incompleteCrossDayCoverageAndDuplicateFillsFailClosed(){ObjectNode p=plan();fill(p,"f","40000","57");p.withObject("fills").put("startDate",DAY.toString());assertThat(run(p,source("orders"),source("rows")).path("status").asText()).isEqualTo("UNAVAILABLE");p.withObject("fills").put("startDate","2026-11-18");fill(p,"f","40000","57");assertThat(run(p,source("orders"),source("rows")).path("status").asText()).isEqualTo("UNAVAILABLE");}
    @Test void unconfirmedFutureAndAmountMismatchCannotBeHidden(){for(String mode:new String[]{"unconfirmed","future","amount"}){ObjectNode p=plan(),f=fill(p,"f","40000","57");switch(mode){case "unconfirmed"->f.put("confirmed",false);case "future"->f.put("tradeDate","2026-11-20");default->f.put("amount","39999");}assertThat(run(p,source("orders"),source("rows")).path("status").asText()).isEqualTo("UNAVAILABLE");}}
    @Test void missingGlobalPendingOrReservationIsUnknown(){assertThat(run(plan(),source("orders").put("coverage","PARTIAL"),source("rows")).path("remainingTwd").isNull()).isTrue();assertThat(run(plan(),source("orders"),source("rows").put("verified",false)).path("status").asText()).isEqualTo("UNAVAILABLE");}
    @Test void orphanAndDuplicateLinksFailClosed(){ObjectNode o=source("orders"),r=source("rows");reserve(r,"r").put("linkedOrderId","missing");assertThat(run(plan(),o,r).path("status").asText()).isEqualTo("UNAVAILABLE");r.withArray("rows").removeAll();order(o,"o");reserve(r,"r1").put("linkedOrderId","o");reserve(r,"r2").put("linkedOrderId","o");assertThat(run(plan(),o,r).path("status").asText()).isEqualTo("UNAVAILABLE");}
    @Test void conflictingPathAttributionAndNegativeFeesFailClosed(){ObjectNode o=source("orders");order(o,"o").put("strategy","NAMED_DEEP_DRAWDOWN_D215");assertThat(run(plan(),o,source("rows")).path("status").asText()).isEqualTo("UNAVAILABLE");o.withArray("orders").removeAll();order(o,"o").put("remainingFees","-1");assertThat(run(plan(),o,source("rows")).path("status").asText()).isEqualTo("UNAVAILABLE");}
    @Test void malformedPolicyCannotIncreaseOrResetBudget(){ObjectNode c=cfg().put("total_buy_budget_twd","800000");assertThat(SrppNamedCashBuyBudget.evaluate(c,plan(),source("orders"),source("rows"),DAY).path("status").asText()).isEqualTo("UNAVAILABLE");c=cfg().put("reset_budget_automatically",true);assertThat(SrppNamedCashBuyBudget.evaluate(c,plan(),source("orders"),source("rows"),DAY).path("status").asText()).isEqualTo("UNAVAILABLE");}
    @Test void duplicateIdsAndConflictingLinkedStrategiesCannotOverstateRemaining(){ObjectNode o=source("orders"),r=source("rows");order(o,"o");order(o,"o");assertThat(run(plan(),o,r).path("status").asText()).isEqualTo("UNAVAILABLE");o.withArray("orders").removeAll();order(o,"o");reserve(r,"r").put("linkedOrderId","o").put("strategy","SHORT_TERM_D173");assertThat(run(plan(),o,r).path("status").asText()).isEqualTo("UNAVAILABLE");r.withArray("rows").removeAll();reserve(r,"r");reserve(r,"r");assertThat(run(plan(),source("orders"),r).path("status").asText()).isEqualTo("UNAVAILABLE");}
    @Test void knownUsedRemainsKnownWhenPendingEvidenceMissingButEntriesCannotMasqueradeAsZero(){ObjectNode p=plan();fill(p,"f","40000","57");JsonNode n=run(p,source("orders").put("coverage","PARTIAL"),source("rows"));assertThat(n.path("usedTwd").asText()).isEqualTo("40057");assertThat(n.path("committedTwd").isNull()).isTrue();assertThat(n.path("remainingTwd").isNull()).isTrue();assertThat(n.path("accountingEntries")).isEmpty();}

    @Test void linkedDebitUsesMaximumOnceInBothDirections(){ObjectNode o=source("orders"),r=source("rows");order(o,"o").put("remainingShares","2500").put("remainingFees","0").put("currency","TWD");reserve(r,"r").put("linkedOrderId","o").put("amount","250000").put("fees","0").put("currency","TWD");JsonNode n=run(plan(),o,r);assertThat(n.path("committedTwd").asText()).isEqualTo("250000");assertThat(n.path("remainingTwd").asText()).isEqualTo("150000");assertThat(n.path("accountingEntries").size()).isEqualTo(1);assertThat(n.path("accountingEntries").get(0).path("cash_debit_twd").asText()).isEqualTo("250000");((ObjectNode)r.path("rows").get(0)).put("amount","50000");assertThat(run(plan(),o,r).path("committedTwd").asText()).isEqualTo("100000");}
    @Test void linkedDifferentCurrencyCannotBecomeCheaperTwdDebit(){for(boolean orderUsd:new boolean[]{false,true}){ObjectNode o=source("orders"),r=source("rows");order(o,"o").put("currency",orderUsd?"USD":"TWD");reserve(r,"r").put("linkedOrderId","o").put("currency",orderUsd?"TWD":"USD");JsonNode n=run(plan(),o,r);assertThat(n.path("status").asText()).isEqualTo("UNAVAILABLE");assertThat(n.path("remainingTwd").isNull()).isTrue();assertThat(n.path("accountingEntries")).isEmpty();}}

    @Test void linkedMissingCurrencyOnEitherOrBothSidesRemainsUnknown(){for(int mode=0;mode<3;mode++){ObjectNode o=source("orders"),r=source("rows");ObjectNode order=order(o,"o"),reservation=reserve(r,"r").put("linkedOrderId","o");if(mode!=1)order.remove("currency");if(mode!=0)reservation.remove("currency");JsonNode n=run(plan(),o,r);assertThat(n.path("status").asText()).isEqualTo("UNAVAILABLE");assertThat(n.path("remainingTwd").isNull()).isTrue();assertThat(n.path("accountingEntries")).isEmpty();}}

    @Test void linkedExplicitOtherPlanCannotBeOverwrittenInEitherDirection(){for(boolean pendingOther:new boolean[]{false,true}){ObjectNode o=source("orders"),r=source("rows");ObjectNode order=order(o,"o"),reservation=reserve(r,"r").put("linkedOrderId","o");if(pendingOther)order.put("planId","OTHER_PLAN");else{reservation.remove("strategy");reservation.put("planId","OTHER_PLAN");}JsonNode n=run(plan(),o,r);assertThat(n.path("status").asText()).isEqualTo("UNAVAILABLE");assertThat(n.path("remainingTwd").isNull()).isTrue();assertThat(n.path("accountingEntries")).isEmpty();}}

    @Test void linkedDifferentExplicitPlansConflictEvenWithSameIndependentStrategy(){ObjectNode o=source("orders"),r=source("rows");order(o,"o").put("planId","INDEPENDENT_PLAN_A").put("strategy","SHORT_TERM_D173");reserve(r,"r").put("linkedOrderId","o").put("planId","INDEPENDENT_PLAN_B").put("strategy","SHORT_TERM_D173");assertThat(run(plan(),o,r).path("status").asText()).isEqualTo("UNAVAILABLE");}
    @Test void ownPlanAndIndependentStrategyCannotAgreeMerelyByLinkedOrderId(){for(boolean orderConflict:new boolean[]{false,true}){ObjectNode o=source("orders"),r=source("rows");ObjectNode order=order(o,"o"),reservation=reserve(r,"r").put("linkedOrderId","o").put("planId",PLAN);if(orderConflict)order.put("strategy","SHORT_TERM_D173");else reservation.put("strategy","NAMED_DEEP_DRAWDOWN_D215");JsonNode n=run(plan(),o,r);assertThat(n.path("status").asText()).isEqualTo("UNAVAILABLE");assertThat(n.path("remainingTwd").isNull()).isTrue();}}

    @Test void linkedDifferentIndependentStrategiesCannotMasqueradeAsSameAttribution(){for(boolean pendingDip:new boolean[]{false,true}){ObjectNode o=source("orders"),r=source("rows");ObjectNode order=order(o,"o");order.remove("planId");order.put("strategy",pendingDip?"NAMED_DEEP_DRAWDOWN_D215":"SHORT_TERM_D173");reserve(r,"r").put("linkedOrderId","o").put("strategy",pendingDip?"SHORT_TERM_D173":"NAMED_DEEP_DRAWDOWN_D215");JsonNode n=run(plan(),o,r);assertThat(n.path("status").asText()).isEqualTo("UNAVAILABLE");assertThat(n.path("remainingTwd").isNull()).isTrue();assertThat(n.path("accountingEntries")).isEmpty();}}

}
